-- GB/T 21063.4-2007 附录A 主题分类：标准标签库 + 资产挂标
-- 一级 21，二级 133

ALTER TABLE ing_asset_tag
  ADD COLUMN parent_id BIGINT NULL COMMENT '父标签ID' AFTER id,
  ADD COLUMN level TINYINT NULL COMMENT '1一级 2二级' AFTER parent_id,
  ADD COLUMN tag_source VARCHAR(16) NOT NULL DEFAULT 'CUSTOM' COMMENT 'STANDARD/CUSTOM' AFTER level,
  ADD COLUMN std_code VARCHAR(16) NULL COMMENT '国标类目编码' AFTER tag_source;

ALTER TABLE ing_asset_tag
  ADD UNIQUE KEY uk_ing_asset_tag_std_code (std_code),
  ADD KEY idx_ing_asset_tag_parent (parent_id),
  ADD KEY idx_ing_asset_tag_source (tag_source);

UPDATE ing_asset_tag SET tag_source = 'CUSTOM' WHERE tag_source IS NULL OR tag_source = '';

CREATE TABLE IF NOT EXISTS ing_asset_tag_binding (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  tag_id BIGINT NOT NULL,
  asset_type VARCHAR(16) NOT NULL COMMENT 'TABLE/COLUMN',
  asset_id BIGINT NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_tag_asset (tag_id, asset_type, asset_id),
  KEY idx_asset (asset_type, asset_id),
  KEY idx_tag (tag_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='资产标签绑定';

